  l  tile=ring_10
  m  tile=ring_00
  n  tile=ring_10 object=rail_i
  o  tile=ring_00 npc=sena id=sena face=SW script=sena
  p  tile=ring_00 object=rail_i
  q  tile=ring_10 npc=psiquico id=t3 face=E trainer=psiquico_g3 range=4 text=tr.psiquico_g3.pre after=tr.psiquico_g3.after
  r  tile=ring_11 object=rail_j
