  t  tile=ring_00 npc=psiquico id=t2 face=W trainer=psiquico_g2 range=4 text=tr.psiquico_g2.pre after=tr.psiquico_g2.after
  u  tile=ring_10 npc=psiquico id=t5 face=S trainer=psiquico_g5 range=4 text=tr.psiquico_g5.pre after=tr.psiquico_g5.after
  v  tile=ring_00 object=orb
