# Dra. Sena. The camera cuts to her; the fight (trainer sena: Trancelf 38, Mirrimime 37, Veilmoth 38, Somnarch 43); a win: her speech, the Medalla Mente (flag 85, the card's 6th badge, an
# eye), what it is, then Disc 07 (a full bag keeps sena_disc clear and she hands it over the next time you talk to her). A loss is the blackout. Afterwards a last line.
@script sena npc
    jf badge_mente after
    npc_face_hero sena
    cam_npc sena
    say gym.sena.pre
    battle sena 0
    jv 0 1 won
    blackout
    end
  won:
    say gym.sena.win
    setf badge_mente
    say gym.sena.badge
    say gym.sena.about
    call sena_gift
    cam_hero
    end
  after:
    npc_face_hero sena
    cam_npc sena
    jf sena_disc said
    call sena_gift
    cam_hero
    end
  said:
    say gym.sena.after
    cam_hero
@end
@script sena_gift called
    say gym.sena.disc
    give_item disc_07 1
    jv 0 0 full
    item_var 0 disc_07
    say gl.gift
    setf sena_disc
    say gym.sena.disc_about
    end
  full:
    say gl.found.full
@end
